for slug,(title,desc,h1,lead,label,kind) in pages.items():
    isimg=kind=='image'
    accept='image/*,.pdf,application/pdf' if slug=='file-checker' else ('image/*' if isimg else 'application/pdf')
    multiple=' multiple' if slug in ('merge-pdf','jpg-to-pdf') else ''
    warning=''
    if slug=='pdf-compressor': warning='<div class="tool-status show info" style="display:block">Important: this strong compression redraws pages as images. Text may stop being selectable and fine print can become blurry. Always inspect the downloaded PDF.</div>'
    if slug=='photo-signature-resizer': warning='<div class="tool-status show info" style="display:block">Use the exact requirements from the latest official application notice. Exam rules can change; KriXo does not claim these custom dimensions are valid for every form.</div>'
    html=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f7f2"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{domain}/tools/{slug}.html"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/assets/styles.css"><script type="module" src="/assets/main.js"></script></head><body data-tool="{slug}"><header id="site-header"></header><main><section class="shell page-hero"><div class="breadcrumb"><a href="/">Home</a> / {label}</div><span class="eyebrow"><i class="eyebrow-dot"></i>{'File utility' if slug=='file-checker' else ('Image utility' if isimg else 'PDF utility')}</span><h1>{h1}</h1><p>{lead}</p></section><section class="shell tool-workspace"><div class="tool-panel"><div class="dropzone" id="dropzone"><input class="file-input" id="file-input" type="file" accept="{accept}"{multiple}><span class="drop-icon"><svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 16V4m-4 4 4-4 4 4"/><path d="M20 16v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-2"/></svg></span><strong id="dropzone-label">Drop your {'file' if slug=='file-checker' else ('image' if isimg else 'PDF')} here</strong><p id="dropzone-sub">or browse files from your device · processed locally</p><button class="browse-btn" type="button" id="browse-btn">Choose {'file' if slug=='file-checker' else ('image' if isimg else 'PDF')}{'s' if multiple else ''}</button></div><div id="file-list" class="file-list"></div>{fields_map[slug]}{warning}<div class="action-row"><button class="btn-primary" id="process-btn" type="button">{'Check file' if slug=='file-checker' else 'Process file'} ↗</button><button class="btn-quiet" id="clear-btn" type="button">Clear</button></div><div id="tool-status" class="tool-status" role="status"></div><div id="result-card" class="result-card"><div class="result-top"><strong id="result-title">Your file is ready</strong><span style="color:#2e8056">✓</span></div><p id="result-detail" class="muted-note"></p><div id="result-stats" class="result-stats"></div><img id="result-preview" class="result-preview hidden" alt="Processed preview"><p><a id="download-result" class="download-btn" href="#" download>Download result ↓</a></p></div></div><aside><div class="side-panel"><h3>How it works</h3><p>{helptext[slug]}</p><div class="info-line"><span class="info-dot"></span><span>No sign-up needed for this tool.</span></div><div class="info-line"><span class="info-dot"></span><span>File processing happens in your browser.</span></div></div><div class="side-panel"><h3>Before you download</h3><ul><li>Check the output file opens correctly.</li><li>Compare the dimensions and file size with your portal rules.</li><li>Keep an original copy of important documents.</li></ul><p>Questions or a bug? <a href="/contact.html" style="color:var(--green);font-weight:800">Send feedback</a>.</p></div></aside></section><section class="shell tool-section"><div class="content-panel"><h2>About this {label.lower()}</h2><p>{desc}</p><h3>Frequently asked questions</h3><details class="faq"><summary>Are my files uploaded to a server?</summary><p>No. This tool uses your browser to read and process the selected file. File contents are not sent to the KriXo backend.</p></details><details class="faq"><summary>Is this tool free?</summary><p>Yes. The first version is free to use without an account. Browser memory and device performance may limit very large files.</p></details><details class="faq"><summary>Will every output meet the portal's requirements?</summary><p>Not automatically. Enter the exact requirements and inspect the output. Some portals apply additional rules that a generic tool cannot detect.</p></details></div></section></main><footer id="site-footer"></footer></body></html>'''
    (root/f'{slug}.html').write_text(html, encoding='utf-8')
